// mobile-tables.js — ПОЛНОСТЬЮ ПЕРЕПИСАННАЯ ВЕРСИЯ

let mobileTablesData = [];
let selectedMobileTableId = null;
let currentSeatsFilter = 'all';
let mobileZones = [];
let currentZoneFilter = '';

window.mobileTablesData = [];

function getClient() {
    return window.supabaseClient;
}

// ===== ИСПОЛЬЗУЕМ ГЛОБАЛЬНЫЕ ДАННЫЕ БРОНЕЙ =====
// Вместо mobileBookingsData используем window.bookingsData из tables.js
// Если window.bookingsData нет — загружаем сами

function getBookingsData() {
    // Если есть глобальные данные из tables.js — используем их
    if (window.bookingsData && window.bookingsData.length > 0) {
        return window.bookingsData;
    }
    // Иначе используем свои
    return window.mobileBookingsData || [];
}

// ===== ЗАГРУЗКА ДАННЫХ =====

async function loadMobileTables() {
    const client = getClient();
    if (!client) {
        setTimeout(loadMobileTables, 500);
        return;
    }
    
    const { data, error } = await client
        .from('tables')
        .select('*')
        .eq('is_active', true)
        .order('id');

    if (error) {
        console.error('Error loading tables:', error);
        return;
    }
    mobileTablesData = (data || []).map(t => ({
        ...t,
        max_seats: t.max_seats || t.seats
    }));
    window.mobileTablesData = [...mobileTablesData];
    mobileZones = [...new Set(mobileTablesData.map(t => t.zone_name))];
    renderMobileZoneButtons();
    renderMobileTableList();
}

// ===== ЗАГРУЗКА БРОНЕЙ В ГЛОБАЛЬНУЮ ПЕРЕМЕННУЮ =====

async function loadMobileBookings() {
    const client = getClient();
    if (!client) return;
    
    const { data, error } = await client
        .from('bookings')
        .select('*')
        .in('status', ['new', 'confirmed']);

    if (error) {
        console.error('Error loading bookings:', error);
        return;
    }

    // Сохраняем в глобальную переменную, чтобы использовать везде
    window.mobileBookingsData = data || [];
    // Также обновляем window.bookingsData если он есть
    if (window.bookingsData !== undefined) {
        window.bookingsData = data || [];
    }
    
    renderMobileTableList();
    updateBookingModalStatus();
}

// ===== ПОЛУЧЕНИЕ АКТУАЛЬНЫХ БРОНЕЙ =====

function getCurrentBookings() {
    // Приоритет: window.bookingsData (из tables.js) > window.mobileBookingsData
    if (window.bookingsData && window.bookingsData.length > 0) {
        return window.bookingsData;
    }
    if (window.mobileBookingsData && window.mobileBookingsData.length > 0) {
        return window.mobileBookingsData;
    }
    return [];
}

// ===== ОТОБРАЖЕНИЕ =====

function renderMobileZoneButtons() {
    const container = document.querySelector('.filter-buttons');
    if (!container) return;
    
    const allZones = [...mobileZones];
    const seatsFilters = ['all', '2', '3', '4', '5', '6+'];
    
    container.innerHTML = 
        '<div class="filter-group" style="display:flex; gap:0.5rem; align-items:center; flex-wrap:wrap; width:100%;">' +
            '<span>Зона:</span>' +
            '<select id="zone-select" class="mobile-filter-select" style="flex:1; min-width:120px;">' +
                allZones.map(z => `<option value="${z}" ${currentZoneFilter === z ? 'selected' : ''}>${z}</option>`).join('') +
            '</select>' +
            '<button id="view-zone-btn" class="btn-view-zone" style="padding:0.4rem 0.8rem; background:var(--primary); color:white; border:none; border-radius:8px; cursor:pointer; font-family:Montserrat,sans-serif; font-size:0.8rem; white-space:nowrap;">Просмотр</button>' +
        '</div>' +
        '<div class="filter-group">' +
            '<span>Места:</span>' +
            '<select id="seats-select" class="mobile-filter-select">' +
                seatsFilters.map(s => {
                    const label = s === 'all' ? 'Все' : (s === '6+' ? '6+' : s);
                    return `<option value="${s}" ${currentSeatsFilter === s ? 'selected' : ''}>${label}</option>`;
                }).join('') +
            '</select>' +
        '</div>';
    
    if (!currentZoneFilter && allZones.length > 0) {
        currentZoneFilter = allZones[0];
        document.getElementById('zone-select').value = currentZoneFilter;
    }
    
    document.getElementById('zone-select').addEventListener('change', function() {
        currentZoneFilter = this.value;
        renderMobileTableList();
    });
    
    document.getElementById('seats-select').addEventListener('change', function() {
        currentSeatsFilter = this.value;
        renderMobileTableList();
    });
    
    document.getElementById('view-zone-btn').addEventListener('click', function() {
        const selectedZone = document.getElementById('zone-select').value;
        if (selectedZone) {
            showZonePhoto(selectedZone);
        } else {
            showToast('Выберите зону', 'warning');
        }
    });
}

