window.selectTableFromPhoto = function(tableNumber) {
    closeZonePhoto();
    const table = mobileTablesData.find(t => t.number === tableNumber.toString());
    if (!table) {
        showToast('Столик не найден', 'warning');
        return;
    }
    selectMobileTable(tableNumber);
};

window.closeZonePhoto = function() {
    const modal = document.getElementById('zone-photo-modal');
    if (modal) {
        modal.style.display = 'none';
        document.body.style.overflow = '';
    }
};

window.showZonePhoto = showZonePhoto;

// ===== ФИЛЬТРАЦИЯ =====

function filterTables(tables) {
    let filtered = tables;
    
    if (currentZoneFilter && currentZoneFilter !== 'all') {
        filtered = filtered.filter(t => t.zone_name === currentZoneFilter);
    }
    
    if (currentSeatsFilter === 'all' || !currentSeatsFilter) return filtered;
    
    const seatsVal = parseInt(currentSeatsFilter);
    if (currentSeatsFilter === '6+') {
        filtered = filtered.filter(t => (t.max_seats || t.seats) >= 6);
    } else if (!isNaN(seatsVal)) {
        filtered = filtered.filter(t => {
            const maxSeats = t.max_seats || t.seats;
            return t.seats <= seatsVal && maxSeats >= seatsVal;
        });
    }
    return filtered;
}

// ===== ОСНОВНОЙ РЕНДЕР =====

function renderMobileTableList() {
    const container = document.getElementById('mobile-tables-container');
    if (!container) return;

    const dateInput = document.getElementById('booking-date');
    const timeSelect = document.getElementById('booking-time');
    const selectedDate = dateInput?.value;
    const selectedTime = timeSelect?.value;

    const filteredTables = filterTables(mobileTablesData);
    
    if (filteredTables.length === 0) {
        container.innerHTML = '<p class="no-tables">Нет столиков</p>';
        return;
    }

    // ПОЛУЧАЕМ АКТУАЛЬНЫЕ БРОНИ
    const bookings = getCurrentBookings();

    container.innerHTML = filteredTables.map(table => {
        let isAvailable = true;
        let availabilityMessage = '';
        
        if (selectedDate && selectedTime) {
            const result = window.checkTableAvailability(bookings, table.id, selectedDate, selectedTime);
            if (result) {
                if (result.message) {
                    availabilityMessage = result.message;
                }
                if (result.available === false) {
                    isAvailable = false;
                }
            }
        }
        
        const statusText = isAvailable ? 'Свободен' : 'Занят';
        const statusClass = isAvailable ? 'available' : 'booked';
        
        return `
            <div class="mobile-table-card ${statusClass}">
                <div class="table-info">
                    <div class="table-header">
                        <span class="table-number">Стол ${table.number}</span>
                        <span class="table-zone">${table.zone_name}</span>
                    </div>
                    <div class="table-details">
                        <span class="table-seats">${table.seats}${table.max_seats && table.max_seats > table.seats ? '-' + table.max_seats : ''} мест</span>
                        <span class="table-status ${statusClass}">${statusText}</span>
                    </div>
                    ${!isAvailable && availabilityMessage ? `<div style="font-size:0.7rem; color:var(--danger); margin-top:0.2rem;">${availabilityMessage}</div>` : ''}
                    ${isAvailable && availabilityMessage ? `<div style="font-size:0.7rem; color:#856404; margin-top:0.2rem;">${availabilityMessage}</div>` : ''}
                </div>
                <button class="book-btn" 
                        onclick="selectMobileTable('${table.number}')"
                        ${!isAvailable ? 'disabled style="opacity:0.5;cursor:not-allowed;"' : ''}>
                    ${isAvailable ? 'Выбрать' : 'Занят'}
                </button>
            </div>
        `;
    }).join('');
}

// ===== ВЫБОР СТОЛА =====

function selectMobileTable(tableNumber) {
    const dateInput = document.getElementById('booking-date');
    const timeSelect = document.getElementById('booking-time');
    const selectedDate = dateInput?.value;
    const selectedTime = timeSelect?.value;
    
    window.clearBookingInfoMessage();
    
    const table = mobileTablesData.find(t => t.number === tableNumber.toString());
    if (!table) {
        showToast('Стол не найден', 'error');
        return;
    }
    
    // ПОЛУЧАЕМ АКТУАЛЬНЫЕ БРОНИ
    const bookings = getCurrentBookings();
    
    if (selectedDate && selectedTime) {
        const result = window.checkTableAvailability(bookings, table.id, selectedDate, selectedTime);
        if (result && result.available === false) {
            window.showBookingInfoInModal(result.message);
            showToast(result.message, 'warning');
            return;
        }
        if (result && result.message) {
            window.showBookingInfoInModal(result.message);
        }
    }
    
    const tableNumberInput = document.getElementById('table-number');
    if (tableNumberInput) {
        tableNumberInput.value = tableNumber;
    }
    
    updateGuestsRangeForTable(tableNumber);
    window.openBookingModal();
    setTimeout(updateBookingModalStatus, 300);
}

// ===== ОБНОВЛЕНИЕ СТАТУСА В МОДАЛКЕ =====

function updateBookingModalStatus() {
    const dateInput = document.getElementById('booking-date');
    const timeSelect = document.getElementById('booking-time');
    const tableInput = document.getElementById('table-number');
    const submitBtn = document.querySelector('#booking-form button[type="submit"]');
    
    const selectedDate = dateInput?.value;
    const selectedTime = timeSelect?.value;
    const tableNumber = tableInput?.value;
    
    if (!selectedDate || !selectedTime || !tableNumber) {
        window.clearBookingInfoMessage();
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'Забронировать';
        }
        return;
    }
    
    const table = mobileTablesData.find(t => t.number === tableNumber.toString());
    if (!table) {
        return;
    }
    
    // ПОЛУЧАЕМ АКТУАЛЬНЫЕ БРОНИ
    const bookings = getCurrentBookings();
    const result = window.checkTableAvailability(bookings, table.id, selectedDate, selectedTime);
    
    if (result) {
        if (result.available === false) {
            window.showBookingInfoInModal(result.message);
            if (submitBtn) {
                submitBtn.disabled = true;
                submitBtn.textContent = '❌ Занят';
            }
        } else if (result.message) {
            window.showBookingInfoInModal(result.message);
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = 'Забронировать';
            }
        } else {
            window.clearBookingInfoMessage();
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = 'Забронировать';
            }
        }
    }
}

function checkMobileBookingAvailability() {
    updateBookingModalStatus();
    renderMobileTableList();
}

// ===== REALTIME =====

function setupMobileRealtime() {
    const client = getClient();
    if (!client) return;
    
    client
        .channel('mobile-bookings')
        .on('postgres_changes', {
            event: '*',
            schema: 'public',
            table: 'bookings'
        }, () => {
            loadMobileBookings();
        })
        .subscribe();
}

// ===== ИНИЦИАЛИЗАЦИЯ =====

function initMobileTables() {
    loadMobileTables();
    loadMobileBookings();
    setupMobileRealtime();
    
    const dateInput = document.getElementById('booking-date');
    const timeSelect = document.getElementById('booking-time');
    const tableInput = document.getElementById('table-number');
    
    if (dateInput) {
        dateInput.addEventListener('change', checkMobileBookingAvailability);
        dateInput.addEventListener('change', renderMobileTableList);
    }
    if (timeSelect) {
        timeSelect.addEventListener('change', checkMobileBookingAvailability);
        timeSelect.addEventListener('change', renderMobileTableList);
    }
    if (tableInput) {
        tableInput.addEventListener('input', checkMobileBookingAvailability);
        tableInput.addEventListener('change', checkMobileBookingAvailability);
    }
    
    const modal = document.getElementById('booking-modal');
    if (modal) {
        const observer = new MutationObserver(() => {
            if (modal.style.display === 'block') {
                setTimeout(updateBookingModalStatus, 300);
            }
        });
        observer.observe(modal, { attributes: true, attributeFilter: ['style'] });
    }
    
    setTimeout(updateBookingModalStatus, 500);
}

// ===== ЭКСПОРТ =====

window.selectMobileTable = selectMobileTable;
window.updateBookingModalStatus = updateBookingModalStatus;
window.checkMobileBookingAvailability = checkMobileBookingAvailability;
window.getCurrentBookings = getCurrentBookings;

document.addEventListener('DOMContentLoaded', () => {
    if (document.getElementById('mobile-tables-container')) {
        initSupabase(function() {
            console.log('Mobile client ready');
            initMobileTables();
        });
    }
});